	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void serializableSnapshotReadDoesNotDeadlockWithConcurrentWriter(@TempDir Path dataDir) throws Exception {
		SailRepository repository = new SailRepository(newStore(dataDir, 100));
		repository.init();
		CountDownLatch firstWriteCommitted = new CountDownLatch(1);
		CountDownLatch firstReadObserved = new CountDownLatch(1);
		CountDownLatch secondWriteCommitted = new CountDownLatch(1);
		ExecutorService executor = Executors.newFixedThreadPool(2, runnable -> {
			Thread thread = new Thread(runnable, "serializable-snapshot-liveness");
			thread.setDaemon(true);
			return thread;
		});
		Future<?> writer = executor.submit(() -> {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.SERIALIZABLE);
				addTestStatement(connection, 1);
				connection.commit();
				firstWriteCommitted.countDown();
				assertTrue(firstReadObserved.await(5, TimeUnit.SECONDS), "reader must observe the first commit");
				connection.begin(IsolationLevels.SERIALIZABLE);
				addTestStatement(connection, 2);
				connection.commit();
				secondWriteCommitted.countDown();
			}
			return null;
		});
		Future<?> reader = executor.submit(() -> {
			try (RepositoryConnection connection = repository.getConnection()) {
				assertTrue(firstWriteCommitted.await(5, TimeUnit.SECONDS), "writer must publish its first commit");
				connection.begin(IsolationLevels.SERIALIZABLE);
				long first = countStatements(connection);
				firstReadObserved.countDown();
				secondWriteCommitted.await(1, TimeUnit.SECONDS);
				long second = countStatements(connection);
				try {
					connection.commit();
				} catch (RuntimeException expectedConflict) {
					connection.rollback();
					return null;
				}
				assertEquals(first, second, "a serializable snapshot must retain the original view");
			}
			return null;
		});

		try {
			try {
				writer.get(10, TimeUnit.SECONDS);
				reader.get(10, TimeUnit.SECONDS);
			} catch (TimeoutException failure) {
				AssertionError assertion = new AssertionError(
						"a serializable reader and writer must not wait while retaining each other's branch locks");
				assertion.initCause(failure);
				throw assertion;
			}
		} finally {
			writer.cancel(true);
			reader.cancel(true);
			executor.shutdownNow();
			if (executor.awaitTermination(3, TimeUnit.SECONDS)) {
				repository.shutDown();
			}
		}
	}

	private static void addTestStatement(RepositoryConnection connection, int id) {
		ValueFactory valueFactory = connection.getValueFactory();
		IRI subject = valueFactory.createIRI("urn:test:subject:" + id);
		IRI predicate = valueFactory.createIRI("urn:test:predicate");
		connection.add(subject, predicate, valueFactory.createLiteral(id));
	}

	private static long countStatements(RepositoryConnection connection) throws Exception {
		long count = 0;
		try (var statements = connection.getStatements(null, null, null, false)) {
			while (statements.hasNext()) {
				statements.next();
				count++;
			}
		}
		return count;
	}

	@Test
	@Timeout(value = 5, unit = TimeUnit.SECONDS)
	void blockedObserverCannotExtendTheSharedGrowthDeadline(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir, 100);
		store.init();
		LmdbSailStore backing = store.getBackingStore();
		CountDownLatch callbackEntered = new CountDownLatch(1);
		CountDownLatch releaseCallback = new CountDownLatch(1);
		LmdbSailStore.MapGrowthObserver observer = (kind, token, deadlineNanos, attempts, views) -> {
			callbackEntered.countDown();
			try {
				releaseCallback.await(5, TimeUnit.SECONDS);
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			}
			return false;
		};
		LmdbSailStore.ReadAttemptLease readAttempt = backing.registerReadAttempt(observer);
		LmdbSailStore.MapGrowthAttempt growthAttempt = backing.beginMapGrowthAttempt(new Object());
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<?> request = executor.submit(() -> {
			growthAttempt.requestQuiescence(LmdbSailStore.MapResizeKind.TRIPLE_STORE);
			return null;
		});

		boolean completedBeforeCallbackRelease = false;
		try {
			assertTrue(callbackEntered.await(2, TimeUnit.SECONDS), "the active reader observer must be notified");
			try {
				request.get(500, TimeUnit.MILLISECONDS);
				completedBeforeCallbackRelease = true;
			} catch (TimeoutException expectedOnCurrentImplementation) {
				// The callback remains blocked until the finally block releases it below.
			}
		} finally {
			releaseCallback.countDown();
			growthAttempt.close();
			readAttempt.close();
			executor.shutdownNow();
			try {
				request.get(2, TimeUnit.SECONDS);
			} catch (ExecutionException ignored) {
				// The assertion below reports the missing deadline bound.
			}
			assertTrue(executor.awaitTermination(2, TimeUnit.SECONDS), "growth coordination must release its worker");
			store.shutDown();
		}

		assertTrue(completedBeforeCallbackRelease,
				"observer work must be bounded by the shared map-growth deadline");
	}

	@Test
	@Timeout(value = 5, unit = TimeUnit.SECONDS)
	void replayCallbackCanAdmitADescendantViewDuringGrowth(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir, 250);
		store.init();
		LmdbSailStore backing = store.getBackingStore();
		CountDownLatch nestedViewOpened = new CountDownLatch(1);
		AtomicReference<LmdbSailStore.MapGrowthObserver> observerRef = new AtomicReference<>();
		AtomicReference<Throwable> callbackFailure = new AtomicReference<>();
		LmdbSailStore.MapGrowthObserver observer = (kind, token, deadlineNanos, attempts, views) -> {
			try (LmdbSailStore.ReadView ignored = backing.createTransactionReadView(observerRef.get())) {
				nestedViewOpened.countDown();
			} catch (RuntimeException | Error failure) {
				callbackFailure.set(failure);
			}
			return true;
		};
		observerRef.set(observer);
		LmdbSailStore.ReadAttemptLease readAttempt = backing.registerReadAttempt(observer);
		LmdbSailStore.MapGrowthAttempt growthAttempt = backing.beginMapGrowthAttempt(new Object());
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<?> request = executor.submit(() -> {
			growthAttempt.requestQuiescence(LmdbSailStore.MapResizeKind.TRIPLE_STORE);
			return null;
		});

		boolean admittedDuringGrowth;
		try {
			admittedDuringGrowth = nestedViewOpened.await(150, TimeUnit.MILLISECONDS);
			if (!admittedDuringGrowth) {
				// Release the current implementation's admission wait so the focused test can finish deterministically.
				growthAttempt.close();
			}
			request.get(2, TimeUnit.SECONDS);
		} finally {
			growthAttempt.close();
			readAttempt.close();
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(2, TimeUnit.SECONDS), "growth coordination must release its worker");
			store.shutDown();
		}

		assertNull(callbackFailure.get(), "a replay callback must be able to open its replacement native view");
		assertTrue(admittedDuringGrowth,
				"nested views belonging to an admitted read attempt must not wait behind their own growth episode");
	}

	@Test
	@Timeout(value = 5, unit = TimeUnit.SECONDS)
	void descendantViewsWaitAfterReplayAndDrainComplete(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir, 250);
		store.init();
		LmdbSailStore backing = store.getBackingStore();
		AtomicReference<LmdbSailStore.MapGrowthObserver> observerRef = new AtomicReference<>();
		LmdbSailStore.MapGrowthObserver observer = (kind, token, deadlineNanos, attempts, views) -> {
			try (LmdbSailStore.ReadView ignored = backing.createTransactionReadView(observerRef.get())) {
				return true;
			} catch (SailException e) {
				throw new AssertionError("replay should admit its descendant view", e);
			}
		};
		observerRef.set(observer);
		LmdbSailStore.ReadAttemptLease readAttempt = backing.registerReadAttempt(observer);
		LmdbSailStore.MapGrowthAttempt growthAttempt = backing.beginMapGrowthAttempt(new Object());
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			growthAttempt.requestQuiescence(LmdbSailStore.MapResizeKind.TRIPLE_STORE);

			Future<LmdbSailStore.ReadView> lateDescendant = executor.submit(
					() -> backing.createTransactionReadView(observer, readAttempt));
			assertThrows(TimeoutException.class, () -> lateDescendant.get(100, TimeUnit.MILLISECONDS));

			growthAttempt.close();
			try (LmdbSailStore.ReadView ignored = lateDescendant.get(2, TimeUnit.SECONDS)) {
				// Admission reopens when the growth episode releases its barrier.
			}
		} finally {
			growthAttempt.close();
			readAttempt.close();
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(2, TimeUnit.SECONDS), "growth coordination must release its worker");
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 5, unit = TimeUnit.SECONDS)
	void writerOwnedReadViewIsExcludedFromReaderDrain(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir, 100);
		store.init();
		LmdbSailStore backing = store.getBackingStore();
		Object owner = new Object();
		AtomicInteger callbackCount = new AtomicInteger();
		LmdbSailStore.MapGrowthObserver observer = (kind, token, deadlineNanos, attempts, views) -> {
			callbackCount.incrementAndGet();
			return false;
		};
		LmdbSailStore.ReadAttemptLease readAttempt = registerOwnedReadAttempt(backing, owner, observer);
		try (var writerOwner = backing.enterWriterOwner(owner);
				LmdbSailStore.ReadView writerView = backing.createTransactionReadView(observer)) {
			LmdbSailStore.MapGrowthAttempt growthAttempt = backing.beginMapGrowthAttempt(owner);
			try (growthAttempt) {
				growthAttempt.requestQuiescence(LmdbSailStore.MapResizeKind.TRIPLE_STORE);
				writerView.ensureNativeSnapshotsValid();
			}
			assertEquals(0, callbackCount.get(), "the growth owner must not be asked to replay its own write view");
		} finally {
			readAttempt.close();
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 5, unit = TimeUnit.SECONDS)
	void shutdownWaitsForRetirementNativeUseAndRejectsNewRetirements(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir, 250);
		store.init();
		LmdbSailStore backing = store.getBackingStore();
		CountDownLatch retirementStarted = new CountDownLatch(1);
		CountDownLatch releaseRetirement = new CountDownLatch(1);
		CountDownLatch nativeReadCompleted = new CountDownLatch(1);
		AtomicBoolean nativeReadSucceeded = new AtomicBoolean();
		AtomicReference<Throwable> retirementFailure = new AtomicReference<>();
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<?> retirement = null;
		try {
			retirement = (Future<?>) invokeStoreApi(backing, "submitReplayRetirement",
					new Class<?>[] { Runnable.class }, (Runnable) () -> {
						retirementStarted.countDown();
						try {
							releaseRetirement.await();
							try (LmdbSailStore.ReadView ignored = backing.createTransactionReadView()) {
								ignored.ensureNativeSnapshotsValid();
								nativeReadSucceeded.set(true);
							}
						} catch (Throwable failure) {
							retirementFailure.set(failure);
						} finally {
							nativeReadCompleted.countDown();
						}
					});
			assertTrue(retirementStarted.await(2, TimeUnit.SECONDS), "the store-owned retirement task should start");

			invokeStoreApi(backing, "stopAcceptingReplayRetirements", new Class<?>[0]);
			assertThrows(RejectedExecutionException.class,
					() -> invokeStoreApi(backing, "submitReplayRetirement", new Class<?>[] { Runnable.class },
							(Runnable) () -> {
							}));

			CountDownLatch shutdownInvoked = new CountDownLatch(1);
			CountDownLatch shutdownCompleted = new CountDownLatch(1);
			Future<?> shutdown = executor.submit(() -> {
				shutdownInvoked.countDown();
				store.shutDown();
				shutdownCompleted.countDown();
				return null;
			});
			assertTrue(shutdownInvoked.await(2, TimeUnit.SECONDS));
			assertFalse(shutdownCompleted.await(100, TimeUnit.MILLISECONDS),
					"store shutdown must wait while a registered retirement may still use native maps");

			releaseRetirement.countDown();
			assertTrue(nativeReadCompleted.await(2, TimeUnit.SECONDS));
			retirement.get(2, TimeUnit.SECONDS);
			shutdown.get(2, TimeUnit.SECONDS);
			assertNull(retirementFailure.get(), "the retirement must finish its paired native read before shutdown");
			assertTrue(nativeReadSucceeded.get());
		} finally {
			releaseRetirement.countDown();
			if (retirement != null) {
				retirement.cancel(true);
			}
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(2, TimeUnit.SECONDS));
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 5, unit = TimeUnit.SECONDS)
	void attemptAdmissionHonorsTheScopedQueryDeadline(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir, 250);
		store.init();
		LmdbSailStore backing = store.getBackingStore();
		LmdbSailStore.MapGrowthAttempt growthAttempt = backing.beginMapGrowthAttempt(new Object());
		QueryExecutionDeadline deadline = QueryExecutionDeadline.start(100);
		CountDownLatch admissionStarted = new CountDownLatch(1);
		AtomicReference<LmdbSailStore.ReadAttemptLease> admitted = new AtomicReference<>();
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<?> admission = executor.submit(() -> {
			try (QueryExecutionDeadline.Scope ignored = deadline.enter()) {
				admissionStarted.countDown();
				admitted.set(backing.registerReadAttempt((kind, token, deadlineNanos, attempts, views) -> false));
			}
		});

		try {
			assertTrue(admissionStarted.await(1, TimeUnit.SECONDS));
			ExecutionException failure = assertThrows(ExecutionException.class,
					() -> admission.get(2, TimeUnit.SECONDS));
			assertTrue(failure.getCause() instanceof QueryInterruptedException,
					"attempt admission must fail with the public query-timeout exception");
		} finally {
			growthAttempt.close();
			deadline.close();
			try {
				admission.get(2, TimeUnit.SECONDS);
			} catch (ExecutionException ignored) {
				// Expected when the scoped deadline expires before the growth barrier opens.
			}
			LmdbSailStore.ReadAttemptLease lease = admitted.get();
			if (lease != null) {
				lease.close();
			}
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(2, TimeUnit.SECONDS));
			store.shutDown();
		}
	}

